    "image": "/questions/coeq/sat-coeq-0992bd73.png",
    "passage": "Social scientists distinguish two different categories of social trust: bonding trust and bridging trust. Bonding trust refers to trust within already existing relationships (e.g., within a family), whereas bridging trust refers to trust between different groups, often involving interactions beyond one’s immediate social circle (e.g., meeting someone at a networking event). In order to evaluate these two aspects of social trust in the United Kingdom, researchers asked par ticipants in 2005, 2018, and 2022 to rate the level of trust they felt for people they know personally and for people they are meeting for the first time. After analyzing the data from the survey responses, the researchers concluded that the level of bonding trust in the UK ______",
