    "image": "/questions/coeq/sat-coeq-8af28416.png",
    "passage": "Organic farming is a method of growing food that tries to reduce environmental harm by using natural forms of pest control and avoiding fer tilizers made with synthetic materials. Organic farms are still a small fraction of the total farms in the United States, but they have been becoming more popular.",
    "stem": "According to the US Depar tment of Agriculture, in 2016 California had between 2,600 and 2,800 organic farms and ______ Which choice most effectively uses data from the graph to complete the text?",
