    "image": "/questions/coeq/sat-coeq-23e2421a.png",
    "passage": "Gabrielle Adams and colleagues reviewed suggestions for improving a university that had been submitted to the university’s president. They coded each suggestion as additive (the idea suggested adding something new to the university), subtractive (the idea suggested removing something from the university), neither additive nor subtractive, or invalid (the idea was not comprehensible). The data illustrated people’s tendency to overlook the possibility of removing things to achieve improvements: ______",
