    "difficulty": "medium",
    "image": "/questions/coeq/sat-coeq-37a49687.png",
    "passage": "Mangroves are trees or bushes that grow on the coastlines of seas and rivers. Areas with mangroves are great places for young fish since they help keep these fish fed and protected while they grow. To study the impor tance of mangroves to young fish, researchers Mohamed A.Abu El- Regal and Nesreen K. Ibrahim collected and identified young fish from three different mangrove sites in the Egyptian Red Sea. They collected fish in the winter, spring, and autumn of 2010, collecting a total of 269 fish from 21 different species. For some species, more fish were collected in the winter than the other two seasons, for instance: ______",
    "stem": "Which choice most effectively uses the data in the graph to complete the example?",
