    "image": "/questions/coeq/sat-coeq-7c21b4b5.png",
    "passage": "A survey listed methods for signing into online accounts. Par ticipants in different countries were asked to choose the sign-in method they view as most secure. The table presents data for two of the methods.",
    "stem": "According to the table, onetime passcodes were viewed as most secure by ______ Which choice most effectively uses data from the table to complete the text?",
