    "image": "/questions/coeq/sat-coeq-a0203977.png",
    "passage": "One measure of international tourism is how much money visitors from abroad spend in a country. A student writing a repor t about tourism in several Asian countries notes that among the countries in the table, most had annual increases in international tourism revenue in 2017 and 2018, but that trend wasn’t universal. For example, ______",
