    "difficulty": "medium",
    "image": "/questions/coeq/sat-coeq-a9040290.png",
    "passage": "Electric companies that use wind turbines rely on weather forecasts to predict the maximum amount of power, in megawatt-hours (MWh), they can generate using wind so that they can determine how much they’ll need to generate from other sources. When winds are stronger than they were forecast to be, however, the predicted maximum amount of electricity wind turbines could generate will be too low. For example, the graph shows that for the West region, the winds were ______",
    "stem": "Which choice most effectively uses data from the graph to complete the example?",
