    "image": "/questions/coeq/sat-coeq-ccf414c9.png",
    "passage": "E-books became an increasingly popular means of reading in the United States in the 2000s and 2010s, though that popularity was concentrated in titles that, like those in most fiction genres, are meant to be read straight through from beginning to end. For books in nonfiction genres that do not tell stories and require the reader to flip back and for th through a volume, e-books were significantly less commercially successful. This can be seen by comparing ______",
