    "difficulty": "medium",
    "image": "/questions/coeq/sat-coeq-cf7491c1.png",
    "passage": "“Hot Jupiters” are gas planets that have a mass of at least 0.25 Jupiters (meaning that their mass is at least 25% of that of Jupiter) and an orbital period of less than 10 days (meaning that they complete one orbit around their star in less than 10 days), while “warm Jupiters” are gas planets that meet the same mass criterion but have orbital periods of more than 10 days. In 2021, Michigan State University astronomer Joseph Rodriguez and colleagues announced the discovery of five new gas exoplanets and asser ted that four are hot Jupiters and one is a warm Jupiter.",
