    "subtopic": "Command of evidence (quantitative / graphs)",
    "difficulty": "medium",
    "image": "/questions/coeq/sat-coeq-d74b9bc6.png",
    "passage": "It is common for freshwater lakes near or above a latitude of 45° nor th of the equator, like Lake Mjøsa in Norway, to accumulate surface ice in winter. The amount and duration of ice depends on many factors, including local weather conditions as well as the lake’s depth, volume, and surface area, but a climate researcher claims that some lakes in these latitudes have seen a decline in the duration of ice between the early 1980s and the mid-2000s. She cites as a typical example ______",
