    "image": "/questions/coeq/sat-coeq-d83c3d54.png",
    "passage": "The Jordanelle Dam was built on the Provo River in Utah in 1992. Ear th scientist Adriana E. Mar tinez and colleagues tracked changes to the environment on the banks of the river downstream of the dam, including how much grass and forest cover were present. They concluded that the dam changed the flow of the river in ways that benefited grass plants but didn’t benefit trees.",
