    "image": "/questions/coeq/sat-coeq-54be8f96.png",
    "passage": "TRAPPIST -1 is a planetary system with a central red dwarf star and several Ear th-sized exoplanets. Each planet in this system is so close in orbit to the star that the gravitational forces acting between the planet and the star cause the planet’s rotational period around its axis and orbital period around the star to be equal. For example, the orbital period of TRAPPIST -1e is ______",
