    "image": "/questions/coeq/sat-coeq-5cf5c0d3.png",
    "passage": "Some researchers studying Indigenous actors and filmmakers in the United States have turned their attention to the early days of cinema, par ticularly the 1910s and 1920s, when people like James Young Deer, Dark Cloud, Edwin Carewe, and Lillian St. Cyr (known professionally as Red Wing) were involved in one way or another with numerous films. In fact, so many films and associated records for this era have been lost that counts of those four figures’ output should be taken as bare minimums rather than totals; it’s entirely possible, for example, that ______",
