    "image": "/questions/coeq/sat-coeq-626a1308.png",
    "passage": "Julianne I. Moses and colleagues have repor ted that Neptune may have cooled significantly between 2003 and 2020. The team reached this conclusion by analyzing existing infrared imaging and spectroscopy data about the planet obtained from various instruments in different years. Of the team’s sources listed in the table, the earliest example of spectroscopy data included in the analysis was obtained in ______",
    "stem": "Which choice most effectively uses data from the table to complete the text?",
    "type": "mcq",
    "options": [
      {
        "id": "A",
        "text": "2007 using TEXES at the Gemini Observatory."
      },
      {
        "id": "B",
        "text": "2007 using T -ReCS at the Gemini Observatory."
      },
      {
        "id": "C",
        "text": "2006 using VISIR at the European Southern Observatory."
      },
      {
        "id": "D",
        "text": "2003 using LWS at the W.M. Keck Observatory."
      }
    ],
    "correctAnswer": "C",
    "explanation": "Choice C is the best answer because it effectively completes the text’s discussion of Moses and colleagues’ analysis of changes in Neptune’s temperature by using data from the table to identify the source of the earliest example of spectroscopy data included in this analysis. The text indicates that Moses and colleagues analyzed infrared imaging and spectroscopy data about Neptune obtained in different years by various instruments. The table lists the observatories where these instruments are housed, the type of data each instrument collected (infrared imaging or spectroscopy), and the years in which the instruments’ observations were made. According to the table, only two of these instruments obtained spectroscopy data: VISIR at the European Southern Observatory, which made its observations in 2006, and TEXES at the Gemini Observatory, which made its observations in later years (2007 and 2019). Although two other instruments are also included in the table, they obtained infrared imaging data, not spectroscopy data. Therefore, the earliest example of spectroscopy data included in the researchers’ analysis is the data obtained by VISIR at the European Southern Observatory in 2006.\n\nChoice A is incorrect. Although the table indicates that TEXES at the Gemini Observatory collected spectroscopy data in 2007 and 2019, the table also indicates that this type of data was collected in 2006 by VISIR at the European Southern Observatory. Because the VISIR data were collected in the previous year, the data obtained in 2007 by TEXES are not the earliest example of spectroscopy data included in Moses and team’s analysis of Neptune’s temperature.\n\nChoice B is incorrect because the table indicates that T -ReCS at the Gemini Observatory collected infrared imaging data, not spectroscopy data. T -ReCS therefore cannot be the source of the earliest example of spectroscopy data that is included in Moses and colleagues’ analysis of Neptune’s temperature. Additionally, the T -ReCS data were collected in 2007, meaning that these data were obtained later than any type of data collected in 2006.\n\nChoice D is incorrect. Although the table indicates that data from LWS at the W.M. Keck\n\nObservatory were obtained in 2003, making these data the earliest example of any type of data included in the analysis, the table also indicates that LWS collected infrared imaging data, not spectroscopy data. LWS therefore cannot be the source of the earliest example of spectroscopy data included in Moses and team’s analysis of Neptune’s temperature."
