    "image": "/questions/coeq/sat-coeq-629fb8a9.png",
    "passage": "A Pew Research Center survey conducted in January 2024 found that three out of ten US adults make at least one New Year’s resolution (a promise for the year ahead), while half of those who make a resolution make more than one. The survey asked par ticipants what kinds of resolutions they made and separated them into several categories. The table presents percentages of people who make par ticular kinds of New Year’s resolutions among those who choose to make them, indexed by age bracket.",
