    "difficulty": "hard",
    "image": "/questions/coeq/sat-coeq-645fd11a.png",
    "passage": "Considering a large sample of companies, economics exper ts Maria Guadalupe, Julie Wulf, and Raghuram Rajan assessed the number of managers and leaders from different depar tments who repor ted directly to a chief executive officer (CEO).",
    "stem": "According to the researchers, the findings suggest that across the years analyzed, there was a growing interest among CEOs in connecting with more depar tments in their companies. Which choice best describes data from the graph that suppor t the researchers’ conclusion?",
