    "explanation": "Choice D is the best answer because it describes data from the graph that suppor t the researchers’ conclusion that there is a growing interest among CEOs in connecting with more depar tments in their companies. The graph shows the average number of individuals repor ting directly to CEOs during three different time periods: the individuals are divided into managers and depar tment leaders. The average number of depar tment leaders directly repor ting to their CEO during the 1991–1995 period was slightly more than three, during the 1996–2001 period it was four, and during the 2001–2008 period it was almost seven. Thus, the average number of depar tment leaders repor ting directly to their CEO rose over the three periods studied, which suggests that CEOs were connecting with more depar tments.\n\nChoice A is incorrect because the average number of managers and depar tment leaders repor ting directly to their CEO rose for both categories between the 1991–1995 and 2001–2008 periods; thus, it isn’t true that the average numbers didn’t fluctuate.\n\nChoice B is incorrect because the average number of managers repor ting directly to their CEO was highest in the 2001–2008 period, not in the 1996–2001 period.\n\nChoice C is incorrect. Although it correctly describes a feature of the graph, the observation that more depar tment leaders than managers are repor ting to CEOs does not by itself address the question of whether CEOs are connecting with more depar tments over time—to address that question, one needs to know whether the number of depar tment leaders repor ting to CEOs is increasing over time."
