    "domainId": "info-ideas",
    "domainName": "2. Information and Ideas",
    "subtopicId": "evidence-quantitative",
    "subtopic": "Command of evidence (quantitative / graphs)",
    "difficulty": "hard",
    "image": "/questions/coeq/sat-coeq-d5b9ed0d.png",
    "passage": "To understand how expressions of anger in reviews of products affect readers of those reviews, business scholar Dezhi Yin and colleagues measured study par ticipants’ responses to three versions of the same negative review—a control review expressing no anger, a review expressing a high degree of anger, and a review expressing a low degree of anger. Reviewing the data, a student concludes that the mere presence of anger in a review may not negatively affect readers’ perceptions of the review, but a high degree of anger in a review does worsen readers’ perceptions of the review.",
